#include <cstdio>
#include <vector>
#include <memory>

struct Node { int v; Node* next; };

int main() {
    const int N = 1000;

    // vector：元素连续，第 i 个由基址 + i*sizeof 直接算出，无需追赶指针
    std::vector<int> v(N, 1);
    long long vector_jumps = 0, sum_v = 0;
    for (int i = 0; i < N; ++i) sum_v += v[i];

    // 链表：每一步都要先解引用 next 才能找到下一个元素 → 一次指针跳转
    std::vector<std::unique_ptr<Node>> pool;
    for (int i = 0; i < N; ++i) pool.push_back(std::make_unique<Node>(Node{1, nullptr}));
    for (int i = 0; i + 1 < N; ++i) pool[i]->next = pool[i + 1].get();

    long long list_jumps = 0, sum_l = 0;
    for (Node* p = pool[0].get(); p; p = p->next) { ++list_jumps; sum_l += p->v; }

    printf("vector 指针跳转=%lld 链表 指针跳转=%lld\n", vector_jumps, list_jumps);
    printf("链表跳转更多: %d\n", (int)(list_jumps > vector_jumps));
    printf("校验 sums: vector=%lld list=%lld\n", sum_v, sum_l);
    return 0;
}
